import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

with zipfile.ZipFile("budget.xlsx") as z:
    print("Archive entries:")
    for n in z.namelist():
        print("  ", n)

    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = []
    for sh in wb_xml.find("m:sheets", NS):
        sheets.append((sh.get("name"), sh.get("sheetId"), sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")))
    print("Sheets:", sheets)

    rels_xml = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_xml:
        rel_map[rel.get("Id")] = rel.get("Target")

    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        sst = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in sst.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    for name, sid, rid in sheets:
        target = rel_map.get(rid)
        if target.startswith("/"):
            target = target[1:]
        else:
            target = "xl/" + target
        print(f"\n--- Sheet: {name} -> {target} ---")
        ws = ET.fromstring(z.read(target))
        sd = ws.find("m:sheetData", NS)
        for row in sd.findall("m:row", NS):
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                val = None
                if v is not None and v.text is not None:
                    if t == "s":
                        val = shared[int(v.text)]
                    elif t == "inlineStr":
                        is_ = c.find("m:is", NS)
                        val = "".join(tt.text or "" for tt in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                    else:
                        val = v.text
                elif t == "inlineStr":
                    is_ = c.find("m:is", NS)
                    val = "".join(tt.text or "" for tt in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                if val is not None:
                    print(f"  {ref}: {val!r}")

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group(0)
    idx = 0
    for ch in letters:
