with zipfile.ZipFile("budget.xlsx") as z:
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        sst = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in sst.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    ws = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    sd = ws.find("m:sheetData", NS)

    cells = {}
    for row in sd.findall("m:row", NS):
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            val = None
            if v is not None and v.text is not None:
                val = shared[int(v.text)] if t == "s" else v.text
            cells[ref] = val

    def cell(row, col):
        return cells.get(f"{col}{row}")

    print("Expense items (rows 11-22, column C):")
    total = 0
    by_category = {}
    for r in range(11, 23):
        cat = cell(r, "A")
        item = cell(r, "B")
        amt = cell(r, "C")
        if amt is not None:
            amt_f = float(amt)
            total += amt_f
            by_category.setdefault(cat, 0.0)
            by_category[cat] += amt_f
            print(f"  {cat} | {item} | {amt}")
        else:
            print(f"  row {r}: no amount (A={cat!r}, B={item!r})")

    print("\nTotals by category:")
    for cat, amt in by_category.items():
        print(f"  {cat}: {amt:.2f}")
    print(f"\nTOTAL EXPENSES: {total:.2f}")

